// ─── File: OutboxReliabilityDemo.java ───
// Demonstrates at-least-once duplicates, idempotent consumer, and retention cleanup.
import java.time.*;
import java.util.*;
import java.util.logging.*;

public class OutboxReliabilityDemo {
    private static final Logger log = Logger.getLogger("Reliability");
    static {
        Logger root = Logger.getLogger("");
        for (Handler h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler ch = new ConsoleHandler();
        ch.setFormatter(new BankLogFormatter());
        root.addHandler(ch);
        root.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        OutboxRepository outboxRepo = new OutboxRepository();
        ProcessedEventRepository processedRepo = new ProcessedEventRepository();
        NotificationConsumer consumer = new NotificationConsumer(processedRepo);

        // Seed one committed outbox row (TransferCompleted for Rajesh).
        OutboxEvent evt = new OutboxEvent("TransferCompleted",
                "{\"from\":\"SAV2001\",\"to\":\"CUR3001\",\"amount\":50000}");
        outboxRepo.save(evt);

        OutboxRelay relay = new OutboxRelay(outboxRepo, consumer);

        // Pass 1: relay sends then crashes BEFORE marking → row still unpublished.
        log.info("--- relay pass 1: send then crash before mark ---");
        relay.drainCrashBeforeMark();
        // Pass 2: relay restarts, re-sends the SAME event, then marks it.
        log.info("--- relay pass 2: restart, re-send, mark ---");
        relay.drain();

        // Retention: mark row old, run cleanup, show table shrink.
        log.info("--- retention cleanup ---");
        evt.backdate(Duration.ofDays(10)); // pretend it is 10 days old and published
        RetentionJob job = new RetentionJob(outboxRepo, 7);
        job.purge();
        log.info(() -> "Outbox rows remaining: " + outboxRepo.size());
    }
}

// ─── Would be in model/OutboxEvent.java ───
class OutboxEvent {
    private final UUID id = UUID.randomUUID();
    private final String eventType;
    private final String payload;
    private boolean published = false;
    private Instant createdAt = Instant.now();
    OutboxEvent(String eventType, String payload) { this.eventType = eventType; this.payload = payload; }
    UUID getId() { return id; }
    String getPayload() { return payload; }
    boolean isPublished() { return published; }
    void markPublished() { published = true; }
    Instant getCreatedAt() { return createdAt; }
    void backdate(Duration d) { createdAt = createdAt.minus(d); }
}

// ─── Would be in repository/OutboxRepository.java ───
class OutboxRepository {
    private final List<OutboxEvent> store = new ArrayList<>();
    void save(OutboxEvent e) { store.add(e); }
    List<OutboxEvent> findUnpublished() {
        List<OutboxEvent> out = new ArrayList<>();
        for (OutboxEvent e : store) if (!e.isPublished()) out.add(e);
        return out;
    }
    // Batched retention delete: remove published rows older than cutoff.
    int deletePublishedOlderThan(Instant cutoff) {
        int before = store.size();
        store.removeIf(e -> e.isPublished() && e.getCreatedAt().isBefore(cutoff));
        return before - store.size();
    }
    int size() { return store.size(); }
}

// ─── Would be in repository/ProcessedEventRepository.java ───
class ProcessedEventRepository {
    private final Set<UUID> seen = new HashSet<>();
    boolean exists(UUID id) { return seen.contains(id); }
    void markProcessed(UUID id) { seen.add(id); }
}

// ─── Would be in service/OutboxRelay.java ───
class OutboxRelay {
    private static final Logger log = Logger.getLogger("Reliability");
    private final OutboxRepository outboxRepo;
    private final NotificationConsumer consumer; // stands in for Kafka + consumer
    OutboxRelay(OutboxRepository outboxRepo, NotificationConsumer consumer) {
        this.outboxRepo = outboxRepo; this.consumer = consumer;
    }
    void drain() {
        for (OutboxEvent e : outboxRepo.findUnpublished()) {
            consumer.onEvent(e.getId(), e.getPayload()); // "publish" to Kafka
            e.markPublished();                            // then mark — order matters
            log.info(() -> "Relay sent and marked " + e.getId());
        }
    }
    void drainCrashBeforeMark() {
        for (OutboxEvent e : outboxRepo.findUnpublished()) {
            consumer.onEvent(e.getId(), e.getPayload());  // sent to Kafka
            log.warning(() -> "Relay CRASHED before marking " + e.getId());
            return; // row remains unpublished → will be re-sent (at-least-once)
        }
    }
}

// ─── Would be in service/NotificationConsumer.java ───
class NotificationConsumer {
    private static final Logger log = Logger.getLogger("Reliability");
    private final ProcessedEventRepository processedRepo;
    NotificationConsumer(ProcessedEventRepository processedRepo) { this.processedRepo = processedRepo; }
    // Idempotent: skip if already processed, else send SMS and record the id.
    void onEvent(UUID eventId, String payload) {
        if (processedRepo.exists(eventId)) {
            log.warning(() -> "Duplicate event " + eventId + " — SKIPPED (idempotent)");
            return;
        }
        log.info(() -> "SMS sent to Rajesh for payload " + payload);
        processedRepo.markProcessed(eventId); // same TX as the SMS record in real code
    }
}

// ─── Would be in service/RetentionJob.java ───
class RetentionJob {
    private static final Logger log = Logger.getLogger("Reliability");
    private final OutboxRepository outboxRepo;
    private final int retentionDays;
    RetentionJob(OutboxRepository outboxRepo, int retentionDays) {
        this.outboxRepo = outboxRepo; this.retentionDays = retentionDays;
    }
    void purge() {
        Instant cutoff = Instant.now().minus(Duration.ofDays(retentionDays));
        int deleted = outboxRepo.deletePublishedOlderThan(cutoff);
        log.info(() -> "Retention deleted " + deleted + " published rows older than "
                + retentionDays + " days");
    }
}

// ─── Would be in config/BankLogFormatter.java ───
class BankLogFormatter extends Formatter {
    @Override public String format(LogRecord r) {
        return String.format("%1$tF %1$tT [%2$s] %3$s%n",
                new java.util.Date(r.getMillis()), r.getLevel(), r.getMessage());
    }
}
